// Turn the Vault enquiry poll response into one item per enquiry.
const res = $json;
const status = res.statusCode;
if (typeof status === 'number' && status >= 300) {
  throw new Error(`VAULT_ENQUIRY_POLL_FAILED: status ${status}`);
}

const payload = res.body ?? res;
const rows = Array.isArray(payload.items) ? payload.items : [];

// REA appends its own structured block to the body. Pull the signals out of it
// and strip it from the text, so the assistant never treats "Postcode: 2148"
// as something the buyer wrote.
function parseBody(raw) {
  const text = String(raw || '');

  const postcode = (text.match(/Postcode:\s*(\d{4})/i) || [])[1] || null;
  const marketStatus = (text.match(/Market Status:\s*(.+)/i) || [])[1]?.trim() || null;
  const financePreApproved = /finance pre-?approval/i.test(text);
  const requested = (text.match(/Requested Information:\s*([\s\S]*?)(?:\n\s*\n|Market Status:|$)/i) || [])[1] || '';

  // Everything before the first REA label is what the buyer actually typed.
  let message = text
    .split(/\n\s*Postcode:|\n\s*Additional information:|\n\s*Requested Information:|\n\s*Market Status:/i)[0]
    .trim();

  // If stripping left only a REA label behind, there is no buyer text at all.
  if (/^(Postcode:|Additional information:|Requested Information:|Market Status:)/i.test(message)) {
    message = '';
  }

  return { message, postcode, marketStatus, financePreApproved, requestedInfo: requested.trim() };
}

return rows.map(r => {
  const subject = r.subject || '';
  const propertyId = (subject.match(/Property ID:\s*(\d+)/) || [])[1] || null;
  const address = (subject.match(/Property ID:\s*\d+,\s*(.+?),\s*Listing Agent/) || [])[1] || null;
  const agentText = (subject.match(/Listing Agent\s+(.+)$/) || [])[1] || '';

  const mobile = (r.personPhoneNumbers || []).find(p => p.typeCode === 'M');
  const anyPhone = (r.personPhoneNumbers || [])[0];
  const parsed = parseBody(r.body);

  return {
    json: {
      __vaultEnquiry: true,
      enquiryId: r.id ?? null,
      enquirySource: r.sourceName || r.source || 'Portal enquiry',
      enquiryMessage: parsed.message || null,
      reaPostcode: parsed.postcode,
      reaMarketStatus: parsed.marketStatus,
      reaFinancePreApproved: parsed.financePreApproved,
      reaRequestedInfo: parsed.requestedInfo,
      enquirySubject: subject,
      enquiryDate: r.enquiryDate ?? r.inserted ?? null,
      processed: r.processed ?? false,
      propertyId,
      propertyAddress: address,
      agentText,
      saleLifeId: r.saleLifeId ?? null,
      leaseLifeId: r.leaseLifeId ?? null,
      contactName: r.personName ?? null,
      contactEmail: (r.personEmails || [])[0] ?? null,
      contactPhone: (mobile?.number ?? anyPhone?.number) ?? null,
      enquiryUnsubEmail: Boolean(r.unsubscribe?.email),
      existingContactId: r.contactId ?? null
    }
  };
});

// Normalise, map the listing agent to a real Vault user, and work out
// whether we are inside PRD office hours (Australia/Sydney).
const TZ = 'Australia/Sydney';
const BUSINESS_START = 8.5;
const BUSINESS_END = 17.5;

// CONFIRMED Vault user IDs. All of these have sendSMS enabled.
const AGENTS = {
  'thomas latty':   { id: 42787,  email: 'thomas.latty@prd.net.au' },
  'jeremy moss':    { id: 42802,  email: 'jeremy@prd.net.au' },
  'ryan hatch':     { id: 108932, email: 'ryan@prd.net.au' },
  'angelina latty': { id: 168169, email: 'angelina@prd.net.au' },
  'stella murina':  { id: 380636, email: 'stella@prd.net.au' },
  'leonie holland': { id: 424379, email: 'admin@prd.net.au' },
  'joe masters':    { id: 42765,  email: 'joe@prd.net.au' },
  'cristina bartuccio': { id: 166878, email: 'cristina@prd.net.au' }
};

// Office sender for outbound SMS - an office address rather than an individual,
// so it survives staff changes.
const SMS_SENDER_ID = 424379; // Leonie Holland, admin@prd.net.au

const t = DateTime.now().setZone(TZ);
const hour = t.hour + t.minute / 60;
const afterHours = t.weekday > 5 || hour < BUSINESS_START || hour >= BUSINESS_END;
const localTime = t.toFormat('ccc dd LLL yyyy, h:mm a');

// Next time the office is staffed, so the assistant never promises "tomorrow morning" on a Friday night.
function nextOpening(t) {
  const open = (d) => d.set({ hour: 8, minute: 30, second: 0, millisecond: 0 });
  let d = t;
  if (!(t.weekday <= 5 && hour < BUSINESS_START)) {
    d = t.plus({ days: 1 });
    while (d.weekday > 5) d = d.plus({ days: 1 });
  }
  d = open(d);
  const sameDay = d.hasSame(t, 'day');
  const nextDay = d.hasSame(t.plus({ days: 1 }), 'day');
  const label = sameDay ? 'this morning' : nextDay ? 'tomorrow morning' : d.toFormat('cccc') + ' morning';
  return { iso: d.toUTC().toISO(), label };
}
const nextOpen = afterHours ? nextOpening(t) : null;
const DEFAULT_HANDOFF = AGENTS['thomas latty'];
// While true, handoff emails go to the REMAP tester, not real PRD agents.
const TEST_MODE = true;
const TEST_NOTIFY = 'suffyan@remap.ai';

const out = [];

for (const item of $input.all()) {
  const src = item.json;

  // Match the first named agent in the subject line against a real Vault user.
  let agent = null;
  const lowered = String(src.agentText || '').toLowerCase();
  for (const [name, info] of Object.entries(AGENTS)) {
    if (lowered.includes(name)) { agent = { name, ...info }; break; }
  }

  // REA sometimes puts the postcode field into the message ("$2148 or a postcode?").
  const rawTyped = String(src.enquiryMessage || '').trim();
  const postcodeOnly = /^(postcode\W*)?\$?\d{4}\W*(or\W+(a\W+)?postcode\W*)?$/i.test(rawTyped);
  const typed = postcodeOnly ? '' : rawTyped;
  const optOutRequested = ['STOP', 'UNSUBSCRIBE', 'OPT OUT', 'OPTOUT']
    .includes(typed.toUpperCase());

  // Many REA enquiries carry no typed message at all - just the structured
  // block. Say so plainly rather than passing a stray label through as if the
  // buyer had written it.
  let message = typed;
  if (!message) {
    message = src.reaRequestedInfo
      ? `(No message typed. They asked for: ${String(src.reaRequestedInfo).replace(/\n/g, '; ')})`
      : '(They enquired through the portal without typing a message.)';
  }

  out.push({
    json: {
      conversationId: `vault_${src.enquiryId}`,
      enquiryId: src.enquiryId,
      externalId: String(src.enquiryId ?? ''),
      channel: src.contactPhone ? 'sms' : 'email',
      source: src.enquirySource,
      message,
      buyerTypedAMessage: Boolean(typed),
      propertyId: src.propertyId,
      propertyAddress: src.propertyAddress,
      saleLifeId: src.saleLifeId,
      reaPostcode: src.reaPostcode ?? null,
      reaMarketStatus: src.reaMarketStatus ?? null,
      reaFinancePreApproved: Boolean(src.reaFinancePreApproved),
      reaRequestedInfo: src.reaRequestedInfo ?? null,
      buyerTypeFromREA: (() => {
        const m = String(src.reaMarketStatus || '').toLowerCase();
        if (!m) return null;
        if (m.includes('first home')) return 'First home buyer';
        if (m.includes('investment')) return 'Investor';
        if (m.includes('keep my current')) return 'Investor';
        if (m.includes('buy and sell') || m.includes('sell property')) return 'Needs to sell first';
        return null;
      })(),
      contactName: src.contactName,
      contactPhone: src.contactPhone,
      contactEmail: src.contactEmail,
      existingContactId: src.existingContactId,
      enquiryUnsubEmail: src.enquiryUnsubEmail,
      isLease: Boolean(src.leaseLifeId),
      enquiryDate: src.enquiryDate,
      agentName: agent?.name ?? null,
      agentUserId: agent?.id ?? null,
      agentEmail: agent?.email ?? null,
      agentAssigned: Boolean(agent),
      handoffAgentEmail: agent?.email ?? DEFAULT_HANDOFF.email,
      notifyEmail: TEST_MODE ? TEST_NOTIFY : (agent?.email ?? DEFAULT_HANDOFF.email),
      nextOpenLabel: nextOpen?.label ?? null,
      nextOpenIso: nextOpen?.iso ?? null,
      smsSenderId: SMS_SENDER_ID,
      optOutRequested,
      receivedAt: new Date().toISOString(),
      localTime,
      afterHours
    }
  });
}

return out;

// Idempotency. The poll window overlaps by design, so the same enquiry arrives
// more than once. n8n static data is unreliable across concurrent executions, so
// we also fingerprint the message itself - the same text from the same person
// is never answered twice.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const now = Date.now();
const TTL_MS = 1000 * 60 * 60 * 24 * 30;
for (const key of Object.keys(store.seen)) {
  if (now - store.seen[key] > TTL_MS) delete store.seen[key];
}

function fingerprint(s) {
  const str = String(s || '');
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h) + str.charCodeAt(i);
    h |= 0;
  }
  return String(h);
}

const out = [];
const seenThisRun = new Set();

for (const item of $input.all()) {
  const j = item.json;

  // Two guards: the enquiry id, and the content of the message itself.
  const idKey = `enquiry:${j.enquiryId}`;
  const msgKey = `msg:${j.contactPhone || j.contactEmail || j.enquiryId}:${fingerprint(j.message)}`;

  if (store.seen[idKey] || store.seen[msgKey]) continue;
  if (seenThisRun.has(idKey) || seenThisRun.has(msgKey)) continue;

  store.seen[idKey] = now;
  store.seen[msgKey] = now;
  seenThisRun.add(idKey);
  seenThisRun.add(msgKey);

  out.push({ json: j });
}

return out;

const d = $json;

const reasons = [];
if (d.optOutRequested) reasons.push('Buyer asked to opt out');
if (d.enquiryUnsubEmail) reasons.push('Enquiry carries an email unsubscribe flag');
if (d.isLease) reasons.push('Leasing enquiry - outside buyer sequencing scope');
if (!d.contactPhone && !d.contactEmail) reasons.push('No contact details supplied');

if (!d.__smsReply && !d.propertyId && !d.saleLifeId) {
  reasons.push('No property reference - not a buyer enquiry, needs a human');
}

// Belt and braces for the obvious non-buyer patterns.
const text = String(d.message || '').toLowerCase();
const notBuyerSignals = [
  'sponsor', 'sponsorship', 'donation', 'fundraising',
  'job application', 'resume', 'cv attached', 'seeking employment',
  'partnership opportunity', 'seo', 'increase your traffic', 'web design services'
];
const hit = notBuyerSignals.find(s => text.includes(s));
if (hit) reasons.push(`Message looks like a non-buyer enquiry (matched "${hit}")`);

const safeToProceed = reasons.length === 0;

return { json: { ...d, blockReasons: reasons, safeToProceed } };

const d = $json;
return {
  json: {
    OUTCOME: 'STOPPED - no contact made',
    conversationId: d.conversationId,
    enquiryId: d.enquiryId,
    who: d.contactName,
    reasons: d.blockReasons,
    stoppedAt: new Date().toISOString()
  }
};

// Build a WHITELISTED fact sheet for the model.
// The raw sale record carries the vendor's marketing spend, the commission rate,
// the agent's internal price appraisal and the authority expiry date. None of
// that may ever reach a buyer, so only the named fields below are passed through.
const res = $json;
const enquiry = $('Resolve Property from Cache').item.json;

// Without a resolved Vault property ID the fetch URL is malformed and Vault
// returns an unrelated record. Never trust the response in that case.
const noId = !enquiry.propertyVaultId;
const status = res.statusCode;
const fetchFailed = noId || (typeof status === 'number' && status >= 300);
const sale = fetchFailed ? {} : ((res.body?.items || [])[0] || {});

const isListed = sale.status === 'listing' || sale.portalStatus === 'listing';

// A withdrawn, sold, leased or prospect record must never reach the model. Quoting
// a price on a property that is no longer for sale is worse than saying nothing,
// so we stop here and hand back no facts at all.
if (!fetchFailed && sale.id && !isListed) {
  return {
    json: {
      ...enquiry,
      knowledgeBase: {
        hasProperty: false,
        hasPrice: false,
        address: sale.displayAddress ?? enquiry.propertyAddress ?? null,
        notCurrentlyListed: true,
        listingStatus: sale.status ?? null,
        openHomes: []
      },
      propertyFetchFailed: false
    }
  };
}

let rates = null;
try {
  const r = typeof sale.rates === 'string' ? JSON.parse(sale.rates) : sale.rates;
  if (r) {
    rates = {
      water: r.water?.value ? `$${r.water.value} ${r.water.period}` : null,
      council: r.council?.value ? `$${r.council.value} ${r.council.period}` : null,
      strata: r.strata?.value ? `$${r.strata.value} ${r.strata.period}` : null
    };
  }
} catch (e) { rates = null; }

const parse = (v) => {
  try { return typeof v === 'string' ? JSON.parse(v) : v; }
  catch (e) { return null; }
};

const land = parse(sale.landArea);

const knowledgeBase = {
  hasProperty: !fetchFailed && Boolean(sale.id) && isListed,
  address: sale.displayAddress ?? enquiry.propertyAddress ?? null,
  propertyType: parse(sale.type)?.name ?? null,
  bedrooms: sale.bed ?? null,
  bathrooms: sale.bath ?? null,
  garages: sale.garages ?? null,
  carports: sale.carports ?? null,
  landArea: land?.value ? `${land.value} ${land.units}` : null,
  displayPrice: sale.displayPrice ?? null,
  heading: sale.heading ?? null,
  description: sale.description ?? null,
  methodOfSale: parse(sale.methodOfSale)?.name ?? null,
  rates,
  status: sale.status ?? null,
  notCurrentlyListed: false,
  // Inspection times are the single most useful thing we can give a buyer.
  openHomes: (() => {
    const oh = sale.openHomes ?? sale.inspectionTimes ?? [];
    if (!Array.isArray(oh)) return [];
    return oh.slice(0, 3).map(o => {
      if (typeof o === 'string') return o;
      const start = o.startTime ?? o.start ?? o.dateTime ?? null;
      const end = o.endTime ?? o.end ?? null;
      if (!start) return null;
      try {
        const s = DateTime.fromISO(String(start)).setZone('Australia/Sydney');
        const e = end ? DateTime.fromISO(String(end)).setZone('Australia/Sydney') : null;
        return e
          ? `${s.toFormat('cccc d LLLL, h:mma')} - ${e.toFormat('h:mma')}`
          : s.toFormat('cccc d LLLL, h:mma');
      } catch (err) { return String(start); }
    }).filter(Boolean);
  })(),
  priceDisplay: sale.displayPrice ?? null,
  hasPrice: Boolean(sale.displayPrice && !/^\s*$/.test(String(sale.displayPrice))) && isListed
};

const rawOh = sale.openHomes ?? sale.inspectionTimes ?? [];
const nowMs = Date.now();
const slots = (Array.isArray(rawOh) ? rawOh : []).map(o => {
  if (!o || typeof o === 'string') return null;
  const start = o.startTime ?? o.start ?? o.dateTime ?? null;
  if (!start) return null;
  const s = DateTime.fromISO(String(start)).setZone('Australia/Sydney');
  if (!s.isValid) return null;
  const endRaw = o.endTime ?? o.end ?? null;
  const e = endRaw ? DateTime.fromISO(String(endRaw)).setZone('Australia/Sydney') : null;
  return { label: e && e.isValid ? `${s.toFormat('cccc d LLLL, h:mma')} - ${e.toFormat('h:mma')}` : s.toFormat('cccc d LLLL, h:mma'), startMs: s.toMillis() };
}).filter(x => x && x.startMs > nowMs).sort((a, b) => a.startMs - b.startMs).slice(0, 6);
knowledgeBase.openHomeSlots = slots;
knowledgeBase.openHomesSoon = slots.filter(x => x.startMs - nowMs <= 48 * 3600 * 1000).map(x => x.label);
if (slots.length) knowledgeBase.openHomes = slots.slice(0, 3).map(x => x.label);

return { json: { ...enquiry, knowledgeBase, propertyFetchFailed: fetchFailed } };

// Conversation memory, rebuilt from the Google Sheet.
// n8n static data does not survive between executions - every buyer reply is its
// own execution - so the sheet is the only durable record of what has already
// been said. Each row is one turn of one conversation.
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.conversationId);

rows.sort((a, b) => String(a.timestamp || '').localeCompare(String(b.timestamp || '')));

const out = [];

for (const item of $('Build Property Fact Sheet').all()) {
  const d = item.json;
  const mine = rows.filter(r => r.conversationId === d.conversationId);

  const history = [];
  for (const r of mine) {
    if (r.buyerMessage) history.push({ role: 'user', content: String(r.buyerMessage) });
    if (r.assistantReply) history.push({ role: 'assistant', content: String(r.assistantReply) });
  }

  // Anything the buyer told us on an earlier turn, so we never ask twice.
  const last = mine[mine.length - 1] || {};
  const priorCapturedFields = {
    buyerType: last.buyerType || null,
    financeStatus: last.financeStatus || null,
    needsToSellFirst: last.needsToSellFirst === 'Yes' ? true : (last.needsToSellFirst === 'No' ? false : null),
    timeframe: last.timeframe || null,
    inspectionInterest: last.inspection || 'not_discussed',
    wantsContract: String(last.wantsContract).toLowerCase() === 'true'
  };

  out.push({
    json: {
      ...d,
      conversationHistory: history,
      priorCapturedFields,
      turns: mine.length,
      cachedContactId: last.contactId || null
    }
  });
}

return out;

// v2 prompt builder. Persona spec: docs/ai/receptionist-persona.md
const d = $json;
const kb = d.knowledgeBase;
const prior = d.priorCapturedFields || {};
const history = d.conversationHistory || [];
const turnCount = history.filter(m => m.role === 'assistant').length;

const cap = (s) => String(s || '').replace(/\b\w/g, c => c.toUpperCase());
const agentFull = d.agentName ? cap(d.agentName) : null;
const agentFirst = agentFull ? agentFull.split(' ')[0] : null;
const agentWho = agentFirst || 'one of the team';

// ---- The property ----
let propertyBlock;
if (kb.hasProperty) {
  const facts = {
    address: kb.address, type: kb.propertyType, bedrooms: kb.bedrooms, bathrooms: kb.bathrooms,
    garages: kb.garages, carports: kb.carports, landOrInternalArea: kb.landArea,
    priceGuide: kb.displayPrice, methodOfSale: kb.methodOfSale, outgoings: kb.rates,
    agentsDescription: kb.description
  };
  propertyBlock = `THE PROPERTY THEY ENQUIRED ON\n${JSON.stringify(facts, null, 2)}\n\nThese are the only property facts you may state, and you must use them.\n- Outgoings, rates, strata -> give the real figures from "outgoings".\n- "Tell me about it" -> describe it: bedrooms, bathrooms, parking, size, price guide, and the one or two things from the agent's description a buyer would care about.\n- Anything genuinely not listed -> say you'll get ${agentWho} to confirm that one thing, then keep going.\nDeferring to the agent when the answer is sitting right here is the single worst thing you can do.`;
} else if (kb.notCurrentlyListed) {
  propertyBlock = `They enquired on ${kb.address}, but it is no longer on the market${kb.listingStatus === 'conditional' ? ' (it is under contract)' : ''}.\nTell them straight away and kindly. State no facts about it: no price, no bedrooms, nothing. Offer to have the team let them know about similar homes. Do not offer an inspection on this property.`;
} else if (kb.address) {
  propertyBlock = `They enquired on ${kb.address}, but we do not have that listing's details to hand. State NO facts about it. Acknowledge the property by address, be upfront that you'll get ${agentWho} to confirm the details, and offer to line up a look.`;
} else {
  propertyBlock = `No property has been matched to this enquiry. State no property facts. Ask warmly which property they were looking at.`;
}

// ---- Inspections: lead with anything inside 48 hours ----
const soon = Array.isArray(kb.openHomesSoon) ? kb.openHomesSoon : [];
const later = Array.isArray(kb.openHomes) ? kb.openHomes : [];
let inspectionBlock;
if (kb.notCurrentlyListed) {
  inspectionBlock = 'Do not offer an inspection on this one.';
} else if (soon.length) {
  inspectionBlock = `OPEN HOME IN THE NEXT 48 HOURS\n${soon.map(o => `- ${o}`).join('\n')}\n\nLead the inspection offer with the first of these, by day and time. Make it easy to say yes to. Also say a private viewing is possible if that time doesn't suit.`;
} else if (later.length) {
  inspectionBlock = `NEXT OPEN HOMES (none in the next two days)\n${later.map(o => `- ${o}`).join('\n')}\n\nOffer the next one by day and time, and mention a private viewing if sooner suits them.`;
} else {
  inspectionBlock = `There is no open home scheduled. Offer a private viewing. Do not invent a time. Ask which part of the week suits them and say ${agentWho} will lock one in around them.`;
}

// ---- Price ----
const priceBlock = !kb.hasProperty ? '' : (kb.hasPrice
  ? `Price guide: ${kb.displayPrice}. Say it plainly if asked. Don't be cagey.`
  : `There is no published price: the vendor hasn't set a guide yet. If they ask, say exactly that, and that ${agentWho} can talk them through where it's likely to land. Do NOT then ask their budget; that reads as dodging and fishing.`);

// ---- When will a person be in touch? Never say "tomorrow morning" on a Friday night ----
const callbackWhen = d.afterHours
  ? `The office is closed. The team is back ${d.nextOpenLabel || 'when the office opens'}. If you promise contact, use exactly that timing and nothing else.`
  : 'The office is open, so someone can come back to them shortly.';

// ---- Handoff: permission before any call or text from a person ----
const lastBuyer = String(d.message || '');
const wantsToSee = prior.inspectionInterest === 'asked_about_it' || prior.inspectionInterest === 'booked'
  || /\b(inspect\w*|see (it|the (place|property|home))|view(ing)?|open home|walk ?through|come (and )?(see|look)|look (at|through) it)\b/i.test(lastBuyer);
let handoffBlock = '';
if (prior.consentOutcome === 'declined') {
  handoffBlock = `They said no to being contacted. Respect it completely. Keep helping by text only and do not ask again.`;
} else if (prior.consentOutcome === 'granted_call' || prior.consentOutcome === 'granted_sms') {
  handoffBlock = `They have agreed to be contacted. Confirm in one short line what happens next (${agentWho} will be in touch ${d.afterHours ? d.nextOpenLabel || 'when the office opens' : 'shortly'}). Ask nothing else about contact.`;
} else if (wantsToSee && !prior.consentAsked && kb.hasProperty) {
  handoffBlock = `They want to see the property. Confirm the time you're offering, then ask ONE permission question: would it be OK for ${agentWho} to give them a quick call or text to lock it in? Word it as something that helps them, not a sales call.`;
}

// ---- Known facts and when to ask about the buyer ----
const knownBits = [];
if (d.buyerTypeFromREA) knownBits.push(`They are a ${d.buyerTypeFromREA.toLowerCase()}.`);
if (d.reaFinancePreApproved) knownBits.push('They have finance pre-approval.');
if (prior.timeframe) knownBits.push(`Their timeframe: ${prior.timeframe}.`);
if (prior.needsToSellFirst === true) knownBits.push('They need to sell a property first.');
if (prior.inspectionInterest === 'booked') knownBits.push('An inspection is already agreed. The team is confirming the time.');
if (prior.wantsContract) knownBits.push('They have asked for the contract. It is on its way.');
const knownBlock = knownBits.length ? `ALREADY KNOWN, never ask any of this again:\n${knownBits.map(b => `- ${b}`).join('\n')}` : '';

const inspectionSorted = prior.inspectionInterest === 'booked' || prior.consentOutcome === 'granted_call' || prior.consentOutcome === 'granted_sms';
const buyerQuestions = inspectionSorted
  ? 'The inspection is sorted, so you may now ask ONE light question about where they are up to (finance, needing to sell first, or timing), but only if it is not already known. If they are happy with what they have, leave it.'
  : 'Do NOT ask about finance, selling first, timing, budget, bedrooms or property type yet. Answer them and get them to an inspection first.';

const stageBlock = turnCount === 0
  ? `This is your FIRST reply. Lead with the answer to their question about THIS property, then offer the inspection. End by saying they can reply STOP to opt out (first message only, never again).`
  : `This is reply number ${turnCount + 1}. They already know who you are and which property it is.\n- Don't repeat that someone will be in touch unless it is new.\n- Don't re-state the address or mention STOP again.\n- One or two sentences is often plenty.`;

const noMessage = d.buyerTypedAMessage === false
  ? `\nThe buyer did not type a message; they enquired through a portal. Treat it as "tell me about this property".`
  : '';

const systemPrompt = `You are the front desk at PRD Penrith, a family-run agency that has been selling in Western Sydney since 1977. You are the first friendly voice a buyer gets, by text, on behalf of the sales team.\n\nWHO YOU ARE\nWarm, local, quick, and genuinely useful, like the best person on a real estate front desk. You know the listing and you say what you know. You are an AI assistant. You never pretend to be a person, and if anyone asks whether they're talking to a bot you say so lightly and plainly ("I'm PRD's virtual assistant, and the team is right behind me") and carry on helping. You do not sign off with a name.\n\n${propertyBlock}\n\n${inspectionBlock}\n\n${priceBlock}\n\n${callbackWhen}\n\n${knownBlock}\n\n${handoffBlock}\n\n${stageBlock}${noMessage}\n\nTHE ORDER OF EVERY CONVERSATION\n1. Answer what they asked about this property, properly, with the real numbers.\n2. Get them to see it: the open home inside 48 hours if there is one, otherwise a private viewing. Make it easy to say yes.\n3. When they want to see it, ask permission for ${agentWho} to call or text to lock it in.\n4. Only then, and only if it helps them, one light question about where they're up to.\n${buyerQuestions}\n\nHOW TO WRITE IT\n- Contractions. Two to three short sentences. It's a text, not an email.\n- Warm, never gushing. No "thank you so much for your wonderful enquiry". No emoji. No exclamation marks unless something really warrants one.\n- Vary your openings. Not every message starts with "Thanks for your enquiry".\n- Never write "I can arrange a private inspection and the agent will confirm a suitable time". It's stiff. Say "Happy to line up a time to see it. Does a weekday or the weekend suit you better?"\n\nGOOD, buyer asks about outgoings:\n"Council's about $1,820 a year, water around $870, and strata is $884 a quarter. Price guide is $469,950 to $489,950. There's an open home Saturday 11 to 11:30 if you'd like a look through."\n\nBAD, same question:\n"Thank you for your enquiry. One of our agents will be in touch to confirm all details including the outgoings."\n\nGOOD, Friday 8pm enquiry, open home Saturday:\n"It's a two-bedroom unit with a lock-up garage, 114sqm all up, freshly painted with new carpet. Open home is tomorrow 11 to 11:30 if you'd like to see it. Reply STOP any time to opt out."\n\nGOOD, buyer says yes to seeing it:\n"Perfect, see you Saturday at 11. Would it be OK if ${agentWho} gave you a quick call or text to confirm?"\n\nTHINGS YOU MUST NEVER DO\n- State a fact that is not in the property details above. Never estimate, guess or round up.\n- Say "tomorrow morning" or "next business morning" unless the timing above says so.\n- Ask what sort of property they want (bedrooms, budget, suburbs). They enquired on a specific home a vendor is paying to advertise.\n- Ask more than one question in a message.\n- Discuss the vendor, why they are selling or what they'll accept.\n- Negotiate, take an offer, or give financial, legal or tax advice.\n- If someone is upset or complaining, don't try to fix it. Acknowledge it briefly, say ${agentWho} will call them personally, and stop there.\n- If they ask for a contract or documents, say it's being sent, and still offer the inspection.`;

const messages = [
  ...history,
  { role: 'user', content: d.message }
];

return { json: { ...d, systemPrompt, messages } };

const res = $json;
const prev = $('Build Conversation Prompt').item.json;

const status = res.statusCode;
if (typeof status === 'number' && status >= 300) {
  throw new Error(`AI_CONVERSATION_FAILED: status ${status} - ${JSON.stringify(res.body)}`);
}

const payload = res.body ?? res;
const reply = payload.choices?.[0]?.message?.content?.trim() || null;

if (!reply) {
  throw new Error('AI_CONVERSATION_FAILED: no message content returned');
}

const conversationHistory = [...prev.messages, { role: 'assistant', content: reply }];

return { json: { ...prev, reply, conversationHistory } };

// Decides whether a buyer is ready for an agent, and how warm they are.
const res = $json;
const prev = $('Parse AI Reply').item.json;

let f = {
  inspectionInterest: 'not_discussed',
  needsToSellFirst: null,
  financeStatus: null,
  hasOfferedElsewhere: null,
  timeframe: null,
  buyerType: null,
  wantsContract: false,
  consentAsked: false,
  consentOutcome: 'not_answered'
};

const status = res.statusCode;
if (!(typeof status === 'number' && status >= 300)) {
  const payload = res.body ?? res;
  const args = payload.choices?.[0]?.message?.tool_calls?.[0]?.function?.arguments;
  if (args) {
    try { f = { ...f, ...JSON.parse(args) }; } catch (e) { /* keep safe defaults */ }
  }
}

// Carry forward anything learned on an earlier turn.
const prior = prev.priorCapturedFields || {};
for (const k of Object.keys(f)) {
  if ((f[k] === null || f[k] === 'not_discussed') && prior[k] != null && prior[k] !== 'not_discussed') {
    f[k] = prior[k];
  }
}

if (prior.consentAsked === true) f.consentAsked = true;
if (f.consentOutcome === 'not_answered' && prior.consentOutcome && prior.consentOutcome !== 'not_answered') f.consentOutcome = prior.consentOutcome;

// REA tells us some of this without asking.
const buyerType = f.buyerType || (() => {
  const t = prev.buyerTypeFromREA;
  if (!t) return null;
  if (t === 'First home buyer') return 'first_home_buyer';
  if (t === 'Investor') return 'investor';
  if (t === 'Needs to sell first') return 'needs_to_sell_first';
  return null;
})();

const financeStatus = f.financeStatus || (prev.reaFinancePreApproved ? 'pre_approved' : null);

// HOT BUYER. Pre-approval alone is too common to mean anything on its own -
// most REA enquiries state it. Hot needs a second signal: a real deadline, an
// offer already made elsewhere, or an inspection actually booked.
const preApproved = financeStatus === 'pre_approved';
const hasDeadline = Boolean(f.timeframe);
const offeredElsewhere = f.hasOfferedElsewhere === true;
const inspectionBooked = f.inspectionInterest === 'booked';

const hotSignals = [hasDeadline, offeredElsewhere, inspectionBooked].filter(Boolean).length;
const isHot = (preApproved && hotSignals >= 1) || offeredElsewhere || (inspectionBooked && hasDeadline);

const temperature = isHot ? 'Hot' : (preApproved || hasDeadline || inspectionBooked ? 'Warm' : 'New');

const consentGranted = f.consentOutcome === 'granted_call' || f.consentOutcome === 'granted_sms';
const consentDeclined = f.consentOutcome === 'declined';

// A buyer goes to an agent when there is something for the agent to act on:
// an inspection to confirm, documents to send, or they have agreed to contact.
const readyForAgent = consentGranted
  || inspectionBooked
  || f.wantsContract
  || f.inspectionInterest === 'asked_about_it'
  || isHot;

// Promise a human response time we can actually be held to.
let slaDueAtIso = null;
if (readyForAgent) {
  const base = prev.afterHours && prev.nextOpenIso ? DateTime.fromISO(prev.nextOpenIso) : DateTime.now();
  slaDueAtIso = base.plus({ hours: 2 }).toUTC().toISO();
}

const whyReady = [
  consentGranted ? 'Agreed to be contacted' : null,
  inspectionBooked ? 'Inspection to confirm' : null,
  f.inspectionInterest === 'asked_about_it' ? 'Wants to inspect' : null,
  f.wantsContract ? 'Asked for the contract' : null,
  isHot ? 'Hot buyer' : null
].filter(Boolean).join('; ');

return {
  json: {
    ...prev,
    capturedFields: { ...f, buyerType, financeStatus },
    buyerType,
    financeStatus,
    temperature,
    isHot,
    inspectionInterest: f.inspectionInterest,
    needsToSellFirst: f.needsToSellFirst,
    timeframe: f.timeframe,
    wantsContract: f.wantsContract,
    consentGranted,
    consentDeclined,
    consentChannel: f.consentOutcome === 'granted_sms' ? 'SMS'
      : f.consentOutcome === 'granted_call' ? 'Phone call' : null,
    consentCapturedAt: consentGranted ? new Date().toISOString() : null,
    readyForAgent,
    handoffStatus: readyForAgent ? 'pending' : 'none',
    slaDueAtIso,
    whyReady: whyReady || 'Not yet',
    turns: (prev.turns || 0) + 1
  }
};

// Vault exposes no contact search, so we keep our own email/phone to contactId
// map. Without it, a returning buyer would get a duplicate record every time.
const store = $getWorkflowStaticData('global');
store.contactIndex = store.contactIndex || {};

const d = $json;
const keys = [
  d.contactEmail ? `e:${String(d.contactEmail).trim().toLowerCase()}` : null,
  d.contactPhone ? `p:${String(d.contactPhone).replace(/\D/g, '').slice(-9)}` : null
].filter(Boolean);

let contactId = d.existingContactId ?? d.cachedContactId ?? null;

if (!contactId) {
  for (const k of keys) {
    const v = store.contactIndex[k];
    if (v && v !== '__pending__') { contactId = v; break; }
  }
}

// Reserve the keys now, so two enquiries from the same person in one batch
// cannot both decide to create a contact.
if (!contactId) {
  for (const k of keys) store.contactIndex[k] = '__pending__';
}

return {
  json: {
    ...d,
    contactId,
    contactIndexKeys: keys,
    needsContactCreate: !contactId
  }
};

// Capture the new contact ID and remember it, so the same person is never
// created twice by this workflow.
const res = $json;
const source = $('Resolve Vault Contact').item.json;

const status = typeof res.statusCode === 'number' ? res.statusCode : 200;
const payload = res.body ?? res;
const newId = payload?.id ?? null;
const failed = status >= 300 || !newId;

if (!failed) {
  const store = $getWorkflowStaticData('global');
  store.contactIndex = store.contactIndex || {};
  for (const k of source.contactIndexKeys) store.contactIndex[k] = newId;

  store.conversations = store.conversations || {};
  const rec = store.conversations[source.conversationId] || {};
  rec.vaultContactId = newId;
  store.conversations[source.conversationId] = rec;
}

return {
  json: {
    ...source,
    contactId: newId ?? source.contactId,
    contactCreateStatus: status,
    contactCreateFailed: failed
  }
};

const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};

const d = $json;
store.conversations[d.conversationId] = {
  history: d.conversationHistory,
  capturedFields: d.capturedFields,
  turns: d.turns,
  vaultContactId: d.contactId ?? null,
  updatedAt: new Date().toISOString()
};

return { json: d };

const d = $json;
return {
  json: {
    OUTCOME: 'Still in conversation - not yet handed to an agent',
    conversationId: d.conversationId,
    who: d.contactName,
    turns: d.turns,
    temperature: d.temperature ?? 'New',
    inspection: d.inspectionInterest ?? 'not_discussed',
    stillNeeded: d.consentDeclined ? 'Buyer declined contact' : 'An inspection, a contract request, or permission to contact'
  }
};

const d = $json;
return {
  json: {
    ALERT: 'AI step failed on a live enquiry - no reply was sent',
    conversationId: d.conversationId ?? 'unknown',
    enquiryId: d.enquiryId ?? 'unknown',
    who: d.contactName ?? 'unknown',
    phone: d.contactPhone ?? 'n/a',
    email: d.contactEmail ?? 'n/a',
    action: 'Manual follow-up needed',
    at: new Date().toISOString()
  }
};

const d = $json;

let rows = [];
try {
  const fetched = $items('Fetch Recent Listings') || [];
  for (const item of fetched) {
    const payload = item.json.body ?? item.json;
    if (Array.isArray(payload.items)) rows.push(...payload.items);
    else if (Array.isArray(payload)) rows.push(...payload);
    else if (payload.id) rows.push(payload);
  }
} catch (e) {
  rows = [];
}

const index = {};
for (const p of rows) {
  if (!p || !p.id) continue;
  const addr = p.address || {};
  const facts = {
    id: p.id,
    displayAddress: p.displayAddress || null,
    suburb: addr.suburb?.name ?? null,
    suburbId: addr.suburb?.id ?? null,
    postcode: addr.suburb?.postcode ?? null,
    saleLifeId: p.saleLifeId ?? null
  };
  if (p.saleLifeId) index[`sale:${p.saleLifeId}`] = facts;
  if (p.displayAddress) {
    const key = p.displayAddress.toLowerCase().replace(/[^a-z0-9]/g, '');
    index[`addr:${key}`] = facts;
  }
}

const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

let match = null;
let matchedOn = null;
let verified = false;
let rejectReason = null;

// A reply already knows its property from the original conversation.
if (d.__smsReply && d.propertyVaultId) {
  return {
    json: {
      ...d,
      propertyMatchedOn: 'carried from conversation',
      propertyMatchRejected: null,
      listingsLoaded: rows.length
    }
  };
}

if (d.saleLifeId && index[`sale:${d.saleLifeId}`]) {
  match = index[`sale:${d.saleLifeId}`];
  matchedOn = 'saleLifeId';
}

if (!match && d.propertyAddress) {
  const key = norm(d.propertyAddress);
  if (index[`addr:${key}`]) {
    match = index[`addr:${key}`];
    matchedOn = 'address';
  } else {
    const prefix = key.slice(0, 30);
    const hit = Object.keys(index).find(k => k.startsWith(`addr:${prefix}`));
    if (hit) { match = index[hit]; matchedOn = 'address-prefix'; }
  }
}

if (match) {
  if (d.propertyAddress && match.displayAddress) {
    const a = norm(d.propertyAddress);
    const b = norm(match.displayAddress);
    verified = a.startsWith(b.slice(0, 20)) || b.startsWith(a.slice(0, 20));
    if (!verified) rejectReason = 'Enquiry address does not match the listing address';
  } else if (!d.propertyAddress) {
    rejectReason = 'No address on the enquiry to confirm the match against';
  }
}

return {
  json: {
    ...d,
    propertyVaultId: verified ? match.id : (d.propertyVaultId ?? null),
    propertyMatchedOn: verified ? matchedOn : null,
    propertyMatchRejected: rejectReason,
    listingsLoaded: rows.length
  }
};

// A buyer has replied by SMS. Work out which conversation it belongs to using
// the sheet, then shape it exactly like an enquiry so the rest of the flow is
// unchanged. The sheet is used rather than n8n static data because static data
// does not survive between executions, and every reply is its own execution.
const TZ = 'Australia/Sydney';
const t = DateTime.now().setZone(TZ);
const hour = t.hour + t.minute / 60;
const afterHours = t.weekday > 5 || hour < 8.5 || hour >= 17.5;

const rows = $input.all().map(i => i.json).filter(r => r && r.conversationId);
rows.sort((a, b) => String(a.timestamp || '').localeCompare(String(b.timestamp || '')));

const digits = (s) => String(s || '').replace(/\D/g, '').slice(-9);

const inbound = $('Buyer SMS Reply').all().map(i => i.json);

const out = [];

for (const raw of inbound) {
  const b = raw.body ?? raw;

  const from = String(b.from ?? b.sender ?? '').trim();
  const text = String(b.message ?? b.body ?? b.text ?? '').trim();
  const tag = String(b.custom_string ?? '').trim();

  if (!from || !text) continue;

  const last9 = digits(from);

  // Prefer the tag sent out with the message. Fall back to the most recent
  // conversation for that phone number.
  let rec = null;

  if (tag) {
    const tagged = rows.filter(r => r.conversationId === tag);
    if (tagged.length) rec = tagged[tagged.length - 1];
  }

  if (!rec) {
    const byPhone = rows.filter(r => digits(r.phone) === last9);
    if (byPhone.length) rec = byPhone[byPhone.length - 1];
  }

  // The property was resolved on the first turn and written to the sheet. Carry
  // it forward - a reply never passes through the listings fetch, so there is
  // nothing to resolve against.
  const mine = rec ? rows.filter(r => r.conversationId === rec.conversationId) : [];
  const withProp = [...mine].reverse().find(r => r.propertyVaultId);

  out.push({
    json: {
      __smsReply: true,
      conversationId: rec?.conversationId || `sms_${last9}`,
      enquiryId: rec?.enquiryId || null,
      externalId: String(b.message_id ?? ''),
      channel: 'sms',
      source: rec?.source || 'SMS reply',
      message: text,
      buyerTypedAMessage: true,
      propertyId: null,
      propertyAddress: rec?.property || null,
      saleLifeId: withProp?.saleLifeId || null,
      propertyVaultId: withProp?.propertyVaultId || null,
      contactName: rec?.buyer || null,
      contactPhone: from,
      contactEmail: rec?.email || null,
      existingContactId: rec?.contactId || null,
      enquiryUnsubEmail: false,
      isLease: false,
      enquiryDate: null,
      reaPostcode: null,
      reaMarketStatus: null,
      reaFinancePreApproved: rec?.financeStatus === 'pre_approved',
      reaRequestedInfo: null,
      buyerTypeFromREA: null,
      agentName: rec?.agent || null,
      agentUserId: withProp?.agentUserId || null,
      agentEmail: withProp?.agentEmail || null,
      smsSenderId: 424379,
      optOutRequested: ['STOP', 'UNSUBSCRIBE', 'OPT OUT', 'OPTOUT'].includes(text.toUpperCase()),
      matchedConversation: Boolean(rec),
      receivedAt: new Date().toISOString(),
      localTime: t.toFormat('ccc dd LLL yyyy, h:mm a'),
      afterHours
    }
  });
}

return out;

