// Test harness. Lets a human type as the buyer so the conversation can be
// exercised end to end without sending a real text message.
// Prefix a message with [conversationId] to choose which buyer you are.
const TZ = 'Australia/Sydney';
const t = DateTime.now().setZone(TZ);
const hour = t.hour + t.minute / 60;
const afterHours = t.weekday > 5 || hour < 8.5 || hour >= 17.5;

const rows = $input.all().map(i => i.json).filter(r => r && r.conversationId);
rows.sort((a, b) => String(a.timestamp || '').localeCompare(String(b.timestamp || '')));

const out = [];

for (const item of $('Test Chat (pretend to be a buyer)').all()) {
  let text = String(item.json.chatInput ?? '').trim();
  const sessionId = String(item.json.sessionId ?? '');

  let wanted = null;
  const tagMatch = text.match(/^\s*\[([^\]]+)\]\s*/);
  if (tagMatch) {
    wanted = tagMatch[1].trim();
    text = text.slice(tagMatch[0].length).trim();
  }

  let rec = null;
  if (wanted) {
    const m = rows.filter(r => r.conversationId === wanted);
    if (m.length) rec = m[m.length - 1];
  }
  if (!rec && rows.length) rec = rows[rows.length - 1];

  if (!text) continue;

  // The property was resolved on the first turn and written to the sheet.
  // Carry it forward rather than resolving again - a reply never passes through
  // the listings fetch, so there is nothing to resolve against.
  const mine = rec ? rows.filter(r => r.conversationId === rec.conversationId) : [];
  const withProp = [...mine].reverse().find(r => r.propertyVaultId);

  out.push({
    json: {
      __smsReply: true,
      __testChat: true,
      chatSessionId: sessionId,
      conversationId: rec?.conversationId || `chat_${sessionId}`,
      enquiryId: rec?.enquiryId || null,
      externalId: sessionId,
      channel: 'sms',
      source: rec?.source || 'Test chat',
      message: text,
      buyerTypedAMessage: true,
      propertyId: null,
      propertyAddress: rec?.property || null,
      saleLifeId: withProp?.saleLifeId || null,
      propertyVaultId: withProp?.propertyVaultId || null,
      contactName: rec?.buyer || 'Test Buyer',
      contactPhone: rec?.phone || '0400000000',
      contactEmail: rec?.email || null,
      existingContactId: rec?.contactId || null,
      enquiryUnsubEmail: false,
      isLease: false,
      enquiryDate: null,
      reaPostcode: null,
      reaMarketStatus: null,
      reaFinancePreApproved: rec?.financeStatus === 'pre_approved',
      reaRequestedInfo: null,
      buyerTypeFromREA: null,
      agentName: rec?.agent || null,
      agentUserId: withProp?.agentUserId || null,
      agentEmail: withProp?.agentEmail || null,
      smsSenderId: 424379,
      optOutRequested: ['STOP', 'UNSUBSCRIBE', 'OPT OUT', 'OPTOUT'].includes(text.toUpperCase()),
      matchedConversation: Boolean(rec),
      receivedAt: new Date().toISOString(),
      localTime: t.toFormat('ccc dd LLL yyyy, h:mm a'),
      afterHours
    }
  });
}

return out;

// Fail open: if the dashboard store is unreachable we still answer (the static-data guard
// upstream remains), but a confirmed duplicate claim stops the run.
const src = $('Safe to Proceed?').item.json;
const r = $json;
const status = r.statusCode;
const duplicate = status === 200 && r.body && r.body.claimed === false;
return {
  json: {
    ...src,
    claimed: !duplicate,
    claimVerified: status === 200,
    blockReasons: duplicate
      ? [...(src.blockReasons || []), 'Duplicate trigger: this message was already answered']
      : (src.blockReasons || [])
  }
};

// Outbound is held until PRD approves. Flip OUTBOUND_LIVE only on written approval
// (and set OUTBOUND_SENDING_LIVE=true in the dashboard so it shows the truth).
// While held, only numbers on ALLOWLIST can receive a real SMS, e.g. Thomas's test phone.
const OUTBOUND_LIVE = false;
const ALLOWLIST = []; // E.164, e.g. '+614XXXXXXXX'

const d = $json;
const to = String(d.contactPhone || '').replace(/\s+/g, '');
const allowed = OUTBOUND_LIVE || ALLOWLIST.includes(to);
if (!allowed || d.optOutRequested) return [];
return { json: d };
